<template>
  <section class="admin-page profile-page">
    <PageHeader title="个人中心" description="当前管理账号资料" />
    <section class="profile-layout">
      <div class="identity-panel"><span class="avatar">{{ initial }}</span><strong>{{ session?.name }}</strong><small>{{ roleLabel }}</small><dl><div><dt>账号 ID</dt><dd>#{{ session?.id }}</dd></div><div><dt>所属分组</dt><dd>{{ session?.groupName || "全平台" }}</dd></div></dl></div>
      <form class="profile-form" @submit.prevent="submit"><label><span>用户名</span><t-input v-model="form.name" maxlength="20" /></label><label><span>新密码</span><t-input v-model="form.password" type="password" maxlength="20" placeholder="不修改请留空" /></label><label><span>确认新密码</span><t-input v-model="form.confirmPassword" type="password" maxlength="20" placeholder="再次输入新密码" /></label><p v-if="formError" class="field-error" role="alert">{{ formError }}</p><p v-if="message" class="operation-message" :class="{ error: failed }" role="status">{{ message }}</p><div class="actions"><t-button type="submit" :loading="saving" :disabled="saving">保存</t-button></div></form>
    </section>
  </section>
</template>
<script setup lang="ts">
import{computed,reactive,ref,watch}from"vue";import{storeToRefs}from"pinia";import PageHeader from"../components/PageHeader.vue";import{adminErrorText,updateCurrentProfile}from"../api/adminApi";import{useAdminSessionStore}from"../session";
const sessionStore=useAdminSessionStore();const{session}=storeToRefs(sessionStore);const form=reactive({name:"",password:"",confirmPassword:""});const saving=ref(false);const formError=ref("");const message=ref("");const failed=ref(false);const initial=computed(()=>session.value?.name.trim().slice(0,1).toUpperCase()||"管");const roleLabel=computed(()=>session.value?.role==="super_admin"?"超级管理员":"分组管理员");watch(session,(value)=>{form.name=value?.name??""},{immediate:true});async function submit(){formError.value="";message.value="";const name=form.name.trim();if(name.length<2){formError.value="用户名至少 2 个字符";return}if(form.password&&form.password.length<6){formError.value="新密码至少 6 个字符";return}if(form.password!==form.confirmPassword){formError.value="两次输入的新密码不一致";return}saving.value=true;try{await updateCurrentProfile({name,...(form.password?{password:form.password}:{})});await sessionStore.fetchSession();form.password="";form.confirmPassword="";failed.value=false;message.value="个人资料已更新"}catch(cause){failed.value=true;message.value=adminErrorText(cause,"个人资料更新失败")}finally{saving.value=false}}
</script>
<style scoped lang="scss">
.admin-page{width:min(100%,900px);margin:0 auto}.profile-layout{display:grid;grid-template-columns:240px minmax(0,1fr);border:1px solid var(--stars-border);border-radius:6px;background:#fff}.identity-panel{display:grid;align-content:start;justify-items:center;padding:24px;border-right:1px solid var(--stars-border)}.avatar{display:grid;width:56px;height:56px;place-items:center;border-radius:50%;background:var(--stars-brand-gradient);color:#fff;font-size:20px;font-weight:700}.identity-panel>strong{margin-top:10px}.identity-panel>small{margin-top:3px;color:var(--stars-text-muted)}dl{width:100%;margin:20px 0 0}dl div{display:flex;justify-content:space-between;padding:9px 0;border-top:1px solid var(--stars-border);font-size:12px}dt{color:var(--stars-text-muted)}dd{margin:0}.profile-form{display:grid;align-content:start;gap:14px;padding:24px}.profile-form label{display:grid;gap:6px}.profile-form label>span{color:var(--stars-text-muted);font-size:12px}.field-error,.operation-message{margin:0;font-size:12px;color:#b91c1c}.operation-message{color:var(--stars-completed)}.operation-message.error{color:#b91c1c}.actions{display:flex;justify-content:flex-end}@media(max-width:680px){.profile-layout{grid-template-columns:1fr}.identity-panel{border-right:0;border-bottom:1px solid var(--stars-border)}}
</style>
